INSERT INTO pregnancy_week_content (week_number, baby_development, maternal_changes, nutrition_guidance, wellness_guidance, routine_note) VALUES (24, 'At around this stage, general development includes continued growth and movement.', 'Many people notice changing energy, comfort and sleep patterns.', 'Aim for varied meals and regular hydration. Personal dietary needs vary.', 'Gentle movement and rest can both be part of a supportive routine.', 'Keep planned check-ups and discuss questions with your healthcare professional.');
